describe('JavaScript Confirm Dialog Confirmation', () => {
  beforeEach(() => {
    cy.visit('/javascript_alerts');
  });

  it('should display confirm dialog and record user choice', () => {
    // Verify initial page state
    cy.get('[data-testid="result"]').should('not.exist');
    cy.get('[data-testid="confirm-button"]').should('be.visible');

    // Click the confirm button to open dialog
    cy.get('[data-testid="confirm-button"]').click();

    // Verify confirm dialog is visible
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');

    // Verify dialog contains confirmation message
    cy.get('[data-testid="confirm-dialog"]').should('contain', 'Are you sure?');

    // Verify result element is still not visible
    cy.get('[data-testid="result"]').should('not.exist');

    // Click 'OK' button in dialog
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-ok-button"]').click();
    });

    // Verify result element now shows 'You clicked: Ok'
    cy.get('[data-testid="result"]').should('be.visible');
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Ok');

    // Verify dialog is closed
    cy.get('[data-testid="confirm-dialog"]').should('not.exist');
  });

  it('should display result element with "Cancel" when dialog is dismissed on second attempt', () => {
    // Verify initial page state
    cy.get('[data-testid="result"]').should('not.exist');
    cy.get('[data-testid="confirm-button"]').should('be.visible');

    // Click the confirm button to open dialog
    cy.get('[data-testid="confirm-button"]').click();

    // Verify confirm dialog is visible
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');

    // Verify dialog contains confirmation message
    cy.get('[data-testid="confirm-dialog"]').should('contain', 'Are you sure?');

    // Click 'OK' button in dialog
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-ok-button"]').click();
    });

    // Verify result element shows 'You clicked: Ok'
    cy.get('[data-testid="result"]').should('be.visible');
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Ok');

    // Click the confirm button again to open dialog
    cy.get('[data-testid="confirm-button"]').click();

    // Verify confirm dialog is visible again
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');

    // Click 'Cancel' button in dialog
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-cancel-button"]').click();
    });

    // Verify result element now shows 'You clicked: Cancel'
    cy.get('[data-testid="result"]').should('be.visible');
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Cancel');

    // Verify dialog is closed
    cy.get('[data-testid="confirm-dialog"]').should('not.exist');
  });
});
